update public.quizzes
set
  title = '¿Qué energía de app de citas traes?',
  description = 'Descubre si eres el alma de la fiesta en Tinder, el misterioso de Bumble o el romántico empedernido de Hinge. Responde estas preguntas y entérate qué vibra proyectas en el mundo del dating digital.',
  questions = '[{"id":"q1","question":"¿Cuál es tu estrategia para la primera foto de perfil?","options":[{"id":"a","text":"Una selfie con luz natural y una sonrisa tímida","personality_tags":["genuino"]},{"id":"b","text":"Una foto en un rooftop con un cocktail, mirando a lo lejos","personality_tags":["enigmatico"]},{"id":"c","text":"Un video corto bailando un trend de TikTok","personality_tags":["divertido"]},{"id":"d","text":"Una foto viajando en un lugar exótico con una mochila","personality_tags":["aventurero"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"Tu bio ideal es:","options":[{"id":"a","text":"Una frase corta y honesta como ''Buscando a mi persona para compartir mates''","personality_tags":["genuino"]},{"id":"b","text":"Un enigma: ''Adivina mi signo y gana una cena''","personality_tags":["enigmatico"]},{"id":"c","text":"Un chiste malo: ''Soy alérgico al drama, pero al aguacate también''","personality_tags":["divertido"]},{"id":"d","text":"Una lista de destinos pendientes: ''Próximo viaje: Japón. ¿Te sumas?''","personality_tags":["aventurero"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"¿Cómo reaccionas cuando recibes un ''hola, ¿cómo te va?''?","options":[{"id":"a","text":"Respondo con un ''¡Bien! ¿Y tú?'' y pregunto algo de su perfil","personality_tags":["genuino"]},{"id":"b","text":"Espero un par de horas y contesto con algo críptico como ''Acá, sobreviviendo''","personality_tags":["enigmatico"]},{"id":"c","text":"Respondo con un meme o un chiste rápido","personality_tags":["divertido"]},{"id":"d","text":"Le propongo directamente un plan: ''¿Viste tal exposición? Vamos''","personality_tags":["aventurero"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Tu app de citas favorita es:","options":[{"id":"a","text":"Hinge, porque está diseñada para borrarse","personality_tags":["genuino"]},{"id":"b","text":"Bumble, porque me gusta que ellas den el primer paso","personality_tags":["enigmatico"]},{"id":"c","text":"Tinder, por la variedad y el factor sorpresa","personality_tags":["divertido"]},{"id":"d","text":"OkCupid, por los prompts y la compatibilidad","personality_tags":["aventurero"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"¿Qué es lo peor que te puede pasar en una cita?","options":[{"id":"a","text":"Que no haya química y se sienta forzado","personality_tags":["genuino"]},{"id":"b","text":"Que la otra persona no deje de hablar de sí misma","personality_tags":["enigmatico"]},{"id":"c","text":"Que sea aburrida y no haya tema de conversación","personality_tags":["divertido"]},{"id":"d","text":"Que cancelen a último minuto","personality_tags":["aventurero"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Tu estilo de cita ideal es:","options":[{"id":"a","text":"Un café tranquilo en un lugar con buena onda","personality_tags":["genuino"]},{"id":"b","text":"Un plan cultural: museo, teatro o cine de autor","personality_tags":["enigmatico"]},{"id":"c","text":"Algo divertido y distinto: bowling, karaoke o minigolf","personality_tags":["divertido"]},{"id":"d","text":"Una actividad al aire libre: hiking, bici o picnic en un parque","personality_tags":["aventurero"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"¿Cuánto tiempo pasas swapeando por semana?","options":[{"id":"a","text":"Poco, prefiero calidad sobre cantidad","personality_tags":["genuino"]},{"id":"b","text":"Solo cuando me aburro, sin obsesionarme","personality_tags":["enigmatico"]},{"id":"c","text":"Un rato cada día, es entretenido","personality_tags":["divertido"]},{"id":"d","text":"El fin de semana, como un ritual de finde","personality_tags":["aventurero"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Si tu perfil fuera una película, sería:","options":[{"id":"a","text":"Una comedia romántica indie","personality_tags":["genuino"]},{"id":"b","text":"Un thriller psicológico con final abierto","personality_tags":["enigmatico"]},{"id":"c","text":"Una comedia absurda tipo ''Superbad''","personality_tags":["divertido"]},{"id":"d","text":"Una película de aventuras como ''Indiana Jones''","personality_tags":["aventurero"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb
