id":"a","text":"No hacer nada productivo","personality_tags":["relajado"]},{"id":"b","text":"Aprender algo nuevo o hacer un taller","personality_tags":["curioso"]},{"id":"c","text":"Conectar con amigos o familia","personality_tags":["social"]},{"id":"d","text":"Completar un proyecto o tarea pendiente","personality_tags":["organizado"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"¿Cómo prefieres comer el fin de semana?","options":[{"id":"a","text":"Pedir delivery y comer en la cama","personality_tags":["relajado"]},{"id":"b","text":"Ir a un restaurante nuevo","personality_tags":["aventurero"]},{"id":"c","text":"Cocinar algo elaborado con amigos","personality_tags":["creativo"]},{"id":"d","text":"Comer algo rápido y seguir con el plan","personality_tags":["activo"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"¿Qué tipo de compañía prefieres?","options":[{"id":"a","text":"Estar solo o con tu mascota","personality_tags":["introspectivo"]},{"id":"b","text":"Un grupo grande de amigos","personality_tags":["fiestero"]},{"id":"c","text":"Una o dos personas de confianza","personality_tags":["social"]},{"id":"d","text":"Tu pareja o mejor amigo","personality_tags":["romántico"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"¿Qué recuerdo quieres llevarte del finde?","options":[{"id":"a","text":"Sensación de paz y descanso","personality_tags":["relajado"]},{"id":"b","text":"Fotos de una aventura o paisaje","personality_tags":["aventurero"]},{"id":"c","text":"Historias divertidas con amigos","personality_tags":["social"]},{"id":"d","text":"Algo nuevo que aprendiste o creaste","personality_tags":["creativo"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb
