update public.quizzes
set
  description = 'Descubre cuál es tu estilo de vacaciones ideal para recargar energías de verdad. Responde estas preguntas y encuentra tu escapada perfecta.',
  questions = '[{"id":"q1","question":"¿Qué es lo primero que piensas al planificar tus vacaciones?","options":[{"id":"a","text":"Quiero desconectar del ruido y estar en contacto con la naturaleza","personality_tags":["naturaleza"]},{"id":"b","text":"Necesito adrenalina y actividades extremas","personality_tags":["aventura"]},{"id":"c","text":"Busco lugares con historia y cultura para explorar","personality_tags":["cultura"]},{"id":"d","text":"Solo quiero descansar, comer rico y no hacer nada","personality_tags":["relax"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"¿Cómo imaginas tu día perfecto de vacaciones?","options":[{"id":"a","text":"Amanecer en la montaña, caminata y fogón al atardecer","personality_tags":["naturaleza"]},{"id":"b","text":"Rafting por la mañana, tirolesa al mediodía y fiesta en la playa","personality_tags":["aventura"]},{"id":"c","text":"Visitar museos, probar comidas típicas y charlar con locales","personality_tags":["cultura"]},{"id":"d","text":"Dormir hasta tarde, desayuno en la cama, pileta y siesta","personality_tags":["relax"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"¿Qué tipo de alojamiento prefieres?","options":[{"id":"a","text":"Una cabaña de madera en medio del bosque","personality_tags":["naturaleza"]},{"id":"b","text":"Un campamento base cerca de rutas de trekking","personality_tags":["aventura"]},{"id":"c","text":"Un hostel boutique en el centro histórico","personality_tags":["cultura"]},{"id":"d","text":"Un resort todo incluido con spa","personality_tags":["relax"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"¿Qué actividad te llama más la atención?","options":[{"id":"a","text":"Hacer kayak en un lago cristalino","personality_tags":["naturaleza"]},{"id":"b","text":"Hacer puenting o parapente","personality_tags":["aventura"]},{"id":"c","text":"Tomar una clase de cocina local","personality_tags":["cultura"]},{"id":"d","text":"Leer un libro en una hamaca","personality_tags":["relax"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"¿Cómo reaccionas ante un cambio de planes inesperado?","options":[{"id":"a","text":"Lo tomo con calma, me adapto y busco una alternativa natural","personality_tags":["naturaleza"]},{"id":"b","text":"Me emociona, es parte de la aventura","personality_tags":["aventura"]},{"id":"c","text":"Investigo rápido nuevas opciones culturales","personality_tags":["cultura"]},{"id":"d","text":"Me estreso, pero si hay un spa cerca me recupero","personality_tags":["relax"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"¿Qué recuerdo de vacaciones te hace más feliz?","options":[{"id":"a","text":"Una puesta de sol en la cima de una montaña","personality_tags":["naturaleza"]},{"id":"b","text":"La vez que me animé a hacer bungee jumping","personality_tags":["aventura"]},{"id":"c","text":"Una conversación fascinante con un guía local","personality_tags":["cultura"]},{"id":"d","text":"Ese día que no hice absolutamente nada y fue perfecto","personality_tags":["relax"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"¿Qué frase describe mejor tu filosofía de viaje?","options":[{"id":"a","text":"''Menos es más, la naturaleza es el mejor hotel''","personality_tags":["naturaleza"]},{"id":"b","text":"''Vivir al límite es la única forma de viajar''","personality_tags":["aventura"]},{"id":"c","text":"''Cada viaje es una oportunidad de aprender''","personality_tags":["cultura"]},{"id":"d","text":"''El mejor viaje es el que no tiene planes''","personality_tags":["relax"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"¿Con qué grupo viajas mejor?","options":[{"id":"a","text":"Solo o con mi pareja, en silencio y en paz","personality_tags":["naturaleza"]},{"id":"b","text":"Con amigos aventureros que se animen a todo","personality_tags":["aventura"]},{"id":"c","text":"Con curiosos que quieran explorar cada rincón","personality_tags":["cultura"]},{"id":"d","text":"Con mi familia o amigos que solo quieran relajarse","personality_tags":["relax"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb
